class CAfxStreams : public advancedfx::IRecordStreamSettings {
public:
    bool m_CampathAutoSave = false;
	bool m_CamExport = false;
	bool m_CamExportSet = false;

    bool GetCampathAutosave() { return m_CampathAutoSave; }
    void SetCampathAutosave(bool value) { m_CampathAutoSave = value; }

	bool CamExport_get(void) { return m_CamExport;  }
	void CamExport_set(bool value) { m_CamExport = value;  }

    CAfxStreams() {
        m_RecordScreen = new CRecordScreen(false, advancedfx::CRecordingSettings::GetDefault());        
    }

	void ShutDown(void) {
        if(m_Shutdown) return;
        m_Shutdown = true;
        RecordEnd();
		delete m_RecordScreen;
        m_RecordScreen = nullptr;
    }    

    ~CAfxStreams(){
        ShutDown();
    }

    const char* GetRecordName() {
        return m_RecordName.c_str();
    }

    void SetRecordName(const char * value) {
        m_RecordName = value;
    }

    bool GetStartMovieWav() {
        return m_StartMovieWav;
    }

    void SetStartMovieWav(bool value) {
        m_StartMovieWav = value;
    }

    bool GetOverrideFps() {
        return m_OverrideFps;
    }

    void SetOverrideFps(bool value) {
        m_OverrideFps = value;
    }

    float GetOverrideFpsValue() {
        return m_OverrideFpsValue;
    }

    void SetOverrideFpsValue(float value) {
        m_OverrideFpsValue = value;
    }

    float GetOutputFpsOverride() {
        return m_OutputFpsOverride;
    }

    void SetOutputFpsOverride(float fps) {
        m_OutputFpsOverride = fps > 0.0f ? fps : 0.0f;
    }

	virtual bool GetStreamFolder(std::wstring& outFolder) const {
        outFolder = m_TakeDir;
        return true;
    }

    const wchar_t * GetTakeDir(void) const {
        return m_TakeDir.c_str();
    }

	virtual advancedfx::StreamCaptureType GetCaptureType() const {
        return m_StreamCaptureType;
    }

    virtual advancedfx::CGrowingBufferPoolThreadSafe * GetImageBufferPool() const {
        return &g_ImageBufferPool;
    }

    virtual bool GetFormatBmpNotTga() const {        
        return m_FormatBmpAndNotTga;
    }

    void SetFormatBmpNotTga(bool value) {
        m_FormatBmpAndNotTga = value;
    }

    void Console_RecordScreen(advancedfx::ICommandArgs* args);

    void Console_Add(advancedfx::ICommandArgs* args);
    void Console_Edit(advancedfx::ICommandArgs* args);
    void Console_Print();
    void Console_Remove(advancedfx::ICommandArgs* args);

    void Console_Edit_RenderCommands(std::list<std::list<std::string>> & commands, advancedfx::ICommandArgs* args);

    void RecordStart();
    void RecordEnd();

    bool GetRecording() { return m_Recording; }
	int GetRecordedSourceFrameCount() const { return m_RecordedSourceFrameCount.load(std::memory_order_acquire); }

    // See AfxStreams_RecordingCapturesAfterUi in the header. Computed at RecordStart and held
    // for the recording's lifetime, so the per-frame gate is a plain bool read.
    bool GetRecordingCapturesAfterUi() { return m_Recording && m_RecordingCapturesAfterUi; }

    void EngineThread_Prepare() {
		if (m_Recording)
			m_RecordedSourceFrameCount.fetch_add(1, std::memory_order_release);
        m_RecordingExtraPassesIterator = m_RecordingExtraPasses.begin();
        m_LiveWorldRefPending = !m_Recording && g_LiveWorldRefWanted.load(std::memory_order_acquire);

        if (m_Recording) {
            if (m_AutoForceFullReSmoke) {
                if (!m_Restore_smoke_volume_lod_ratio_change) {
                    m_Old_smoke_volume_lod_ratio_change = Update_smoke_volume_lod_ratio_change(0.0f);
                    if (m_Old_smoke_volume_lod_ratio_change != 0.0f) m_Restore_smoke_volume_lod_ratio_change = true;
                }
                if (!m_Restore_r_csgo_mboit_force_mixed_resolution) {
                    m_Old_r_csgo_mboit_force_mixed_resolution = Update_r_csgo_mboit_force_mixed_resolution(false);
                    if (m_Old_r_csgo_mboit_force_mixed_resolution != false) m_Restore_r_csgo_mboit_force_mixed_resolution = true;
                }
            }
        }
        else {
            m_AutoForceFullReSmoke = false;
            if (m_Restore_smoke_volume_lod_ratio_change) {
                m_Restore_smoke_volume_lod_ratio_change = false;
                Update_smoke_volume_lod_ratio_change(m_Old_smoke_volume_lod_ratio_change);
            }
            if (m_Restore_r_csgo_mboit_force_mixed_resolution) {
                m_Restore_r_csgo_mboit_force_mixed_resolution = false;
                Update_r_csgo_mboit_force_mixed_resolution(m_Old_r_csgo_mboit_force_mixed_resolution);
            }
        }
    }

    bool EngineThread_HasNextRenderPass() {
        return m_RecordingExtraPassesIterator != m_RecordingExtraPasses.end() || m_LiveWorldRefPending;
    }

    void EngineThread_BeginNextRenderPass() {
        ++m_ExtraPassGroupCounter;
        g_RenderCommands.EngineThread_GetCommands().PassOrdinal = m_ExtraPassGroupCounter;
        if (m_LiveWorldRefPending && m_RecordingExtraPassesIterator == m_RecordingExtraPasses.end()) {
            // The live Players Only view's World Only reference (never shown: present suppressed).
            BeginPassRender((int)Filmmaker::RenderKey::WorldOnly);
            g_RenderCommands.EngineThread_GetCommands().BeforeUi.Push([](ID3D11DeviceContext * pDeviceContext, ID3D11Texture2D * pTexture){
                AfxRenderPass::StoreWorldReference(pDeviceContext, g_pCurrentDepthStencilView);
            });
            return;
        }
        if (m_RecordingExtraPassesIterator != m_RecordingExtraPasses.end())
            BeginPassRender(m_RecordingExtraPassesIterator->GetSettings().PassRenderKey());
        auto it = m_RecordingExtraPassesIterator;
        while(it != m_RecordingExtraPasses.end()) {
            it->EngineThread_BeginFrame();

            auto last_it = it;
            it++;
            if(it == m_RecordingExtraPasses.end()) break; // done.
            if(last_it->CompareRenderPass(*it) != 0) break; // done for this render pass.
        }
    }

    void EngineThread_EndNextRenderPass() {
        if (m_LiveWorldRefPending && m_RecordingExtraPassesIterator == m_RecordingExtraPasses.end()) {
            m_LiveWorldRefPending = false;
            EndPassRender();
            EngineThread_Suppress_Present();
            return;
        }
        // End in reverse begin order: each stream restores the cvars its begin saw, so the first
        // stream (which saved the user's values) has to restore last.
        std::vector<const CStream *> group;
        while(m_RecordingExtraPassesIterator != m_RecordingExtraPasses.end()) {
            group.push_back(&*m_RecordingExtraPassesIterator);

            auto last_it = m_RecordingExtraPassesIterator;
            m_RecordingExtraPassesIterator++;
            if(m_RecordingExtraPassesIterator == m_RecordingExtraPasses.end()) break; // done.
            if(last_it->CompareRenderPass(*m_RecordingExtraPassesIterator) != 0) break; // done for this render pass.
        }
        for(auto it = group.rbegin(); it != group.rend(); it++) (*it)->EngineThread_EndFrame();

        EndPassRender();
        EngineThread_Suppress_Present();
    }

    void EngineThread_BeginMainRenderPass() {
        m_ExtraPassGroupCounter = 0;
        g_RenderCommands.EngineThread_GetCommands().PassOrdinal = 0;
        // The Main render is always the full scene: state it (see BeginPassRender).
        if (m_Recording) BeginPassRender((int)Filmmaker::RenderKey::Main);
        if (m_Recording && m_PassNeedsMainReference) {
            // Gun Only passes are the difference between this Main render and the NoGun render of
            // the SAME frame: keep Main's colour and depth before the extra renders overwrite them.
            g_RenderCommands.EngineThread_GetCommands().BeforeUi.Push([](ID3D11DeviceContext * pDeviceContext, ID3D11Texture2D * pTexture){
                AfxRenderPass::StoreReference(pDeviceContext, pTexture, g_pCurrentDepthStencilView);
            });
        }
        for(auto it = m_RecordingMainPass.begin(); it != m_RecordingMainPass.end(); it++) {
            it->EngineThread_BeginFrame();
        }

        if(m_Recording) {
            auto & pRenderPassCommands = g_RenderCommands.EngineThread_GetCommands();

            if(g_ActiveCapture) {
                {
                    auto & queue = pRenderPassCommands.BeforePresent;
                    CAfxCapture * capture = g_ActiveCapture;
                    queue.Push([capture](ID3D11DeviceContext * pDeviceContext, ID3D11Texture2D * pTexture){
                        capture->OnBeforeGpuPresent(pDeviceContext, pTexture, 1.0f, 0.0f);
                    }); 
                }
                {
                    auto & queue = pRenderPassCommands.AfterPresent;
                    CAfxCapture * capture = g_ActiveCapture;
                    queue.Push([capture](ID3D11DeviceContext * pDeviceContext){
                        capture->OnAfterGpuPresent(pDeviceContext);
                    }); 
                }
            }
        }
    }

    void EngineThread_EndMainRenderPass() {
        // Reverse begin order, so saved cvars unwind to the user's values (see EndNextRenderPass).
        for(auto it = m_RecordingMainPass.rbegin(); it != m_RecordingMainPass.rend(); it++) {
            it->EngineThread_EndFrame();
        }
        g_CurrentPassRenderKey.store(-1, std::memory_order_release);

        if(EngineThread_HasNextRenderPass()) EngineThread_Expect_Present();
    }

    // --- Filmmaker render-job control surface (see RenderSystemDX11Hooks.h) ---

    bool GetRecordScreenEnabled() { return m_RecordScreen && m_RecordScreen->Enabled; }
    void SetRecordScreenEnabled(bool enabled) { if (m_RecordScreen) m_RecordScreen->Enabled = enabled; }

    const char * GetRecordScreenSettingsName() {
        return (m_RecordScreen && m_RecordScreen->Settings) ? m_RecordScreen->Settings->GetName() : "";
    }

    bool SetRecordScreenSettingsByName(const char * name) {
        if (!m_RecordScreen || !name) return false;
        if (advancedfx::CRecordingSettings* settings = advancedfx::CRecordingSettings::GetByName(name)) {
            settings->AddRef();
            m_RecordScreen->Settings->Release();
            m_RecordScreen->Settings = settings;
            return true;
        }
        return false;
    }

    bool HasStream(const char * name) {
        return name && m_Streams.find(name) != m_Streams.end();
    }

    bool AddNormalStream(const char * name, bool beforeUi, const char * settingsName) {
        if (!name || m_Recording || m_Streams.find(name) != m_Streams.end()) return false;
        advancedfx::CRecordingSettings * recSettings = settingsName
            ? advancedfx::CRecordingSettings::GetByName(settingsName)
            : advancedfx::CRecordingSettings::GetDefault();
        if (!recSettings) return false;
        CStreamSettings settings(recSettings);
        settings.Capture = beforeUi ? CStreamSettings::Capture_e::BeforeUi
                                    : CStreamSettings::Capture_e::BeforePresent;
        if (!UTF8StringToWideString(name, settings.Name)) return false;
        auto it = m_Streams.begin();
        if (it != m_Streams.end()) settings.AutoForceFullResSmoke = it->second.AutoForceFullResSmoke;
        m_Streams.emplace(name, settings);
        return true;
    }

    // One Filmmaker multipass stream (Filmmaker/Render/RenderPassPlan.h). Always captured at the
    // BeforeUi boundary of its render, which is the only point where the scene colour AND depth of
    // that render are both bound. Streams whose visible elements are Everything are taken from the
    // Main render; the rest share one extra render per render key.
    bool AddPassStream(const char * name, int passType, int passElements, const char * settingsName,
        float depthNear, float depthFar, const float keyOut[3]) {
        if (!name || m_Recording || m_Streams.find(name) != m_Streams.end()) return false;
        if (passType < 0 || passType >= (int)Filmmaker::PassType::Count) return false;
        if (passElements < 0 || passElements >= (int)Filmmaker::VisibleElements::Count) return false;
        advancedfx::CRecordingSettings * recSettings = settingsName
            ? advancedfx::CRecordingSettings::GetByName(settingsName)
            : advancedfx::CRecordingSettings::GetDefault();
        if (!recSettings) return false;
        CStreamSettings settings(recSettings);
        settings.Capture = CStreamSettings::Capture_e::BeforeUi;
        settings.PassType = passType;
        settings.PassElements = passElements;
        settings.PassDepthNear = depthNear;
        settings.PassDepthFar = depthFar;
        if (keyOut) { settings.PassKeyOut[0] = keyOut[0]; settings.PassKeyOut[1] = keyOut[1]; settings.PassKeyOut[2] = keyOut[2]; }
        if (!UTF8StringToWideString(name, settings.Name)) return false;
        auto it = m_Streams.begin();
        if (it != m_Streams.end()) settings.AutoForceFullResSmoke = it->second.AutoForceFullResSmoke;
        m_Streams.emplace(name, settings);
        return true;
    }

    bool SetStreamFolder(const char * name, const char * folderUtf8) {
        if (!name || m_Recording) return false; // a running stream's folder is already open
        auto it = m_Streams.find(name);
        if (it == m_Streams.end()) return false;
        std::wstring folder;
        if (folderUtf8 && *folderUtf8 && !UTF8StringToWideString(folderUtf8, folder)) return false;
        it->second.Folder = folder;
        return true;
    }

    bool GetRecordTakeSubfolder() const { return m_RecordTakeSubfolder; }
    void SetRecordTakeSubfolder(bool value) { m_RecordTakeSubfolder = value; }

    bool RemoveStream(const char * name) {
        if (!name || m_Recording) return false; // never mutate the stream set mid-recording
        auto it = m_Streams.find(name);
        if (it == m_Streams.end()) return false;
        m_Streams.erase(it);
        return true;
    }

    // --- Filmmaker multipass: render state shared by every stream of one extra render ----------
    //
    // Engine thread, bracketing one extra render (BeginNextRenderPass .. EndNextRenderPass). The
    // extra render re-runs the client's render output on the SAME simulation state as the Main
    // render, so everything set here changes only what that render draws, never what happens.
    //   * every extra render hides the first-person viewmodel (r_drawviewmodel is consulted by the
    //     client's view setup, which the extra render re-runs; measured to work per pass);
    //   * World Only drops players and gear at the scene draw hook;
    //   * Players Only is the NoGun render, masked by depth against World Only (no repaint).
    // The draw-hook policies run on the render thread, so they are published through the reliable
    // Begin/End queues of this render, and primed here for the engine-thread scene update that
    // follows immediately.
    void BeginPassRender(int key) {
        m_PassRenderKey = key;
        // The one source of truth for what this render draws (see g_CurrentPassRenderKey): set
        // before its scene update, cleared after it has been waited for.
        g_CurrentPassRenderKey.store(key, std::memory_order_release);
        if (key <= (int)Filmmaker::RenderKey::Main) return;
        m_PassViewmodelSaved = SetBoolCvar("r_drawviewmodel", false, &m_PassViewmodelOld);
    }

    void EndPassRender() {
        // Called after the render was waited for: nothing of it is still drawing.
        if (m_PassViewmodelSaved) {
            SetBoolCvar("r_drawviewmodel", m_PassViewmodelOld, nullptr);
            m_PassViewmodelSaved = false;
        }
        m_PassRenderKey = -1;
        g_CurrentPassRenderKey.store(-1, std::memory_order_release);
    }

    // Direct convar write with the change callback, like the stream before/after commands, so the
    // value is in effect for the render that follows (a console command would be deferred).
    static bool SetBoolCvar(const char * name, bool value, bool * outOld) {
        auto handle = SOURCESDK::CS2::g_pCVar->FindConVar(name, false);
        SOURCESDK::CS2::Cvar_s * cvar = SOURCESDK::CS2::g_pCVar->GetCvar(handle.Get());
        if (!cvar || cvar->m_eVarType != SOURCESDK::CS2::EConVarType_Bool) return false;
        SOURCESDK::CS2::CVValue_t oldValue = {};
        oldValue.m_bValue = cvar->m_Value.m_bValue;
        if (outOld) *outOld = oldValue.m_bValue;
        cvar->m_Value.m_bValue = value;
        SOURCESDK::CS2::g_pCVar->CallChangeCallback(handle, 0, &cvar->m_Value, &oldValue);
        return true;
    }

    int m_PassRenderKey = -1;
    bool m_PassViewmodelSaved = false;
    bool m_PassViewmodelOld = true;
    bool m_PassNeedsMainReference = false;
    bool m_LiveWorldRefPending = false; // engine thread, per frame (see g_LiveWorldRefWanted)

private:
    class CStream : public advancedfx::IRecordStreamSettings {
	public:
		CStream(CAfxStreams * streams, const CStreamSettings & settings)
			: m_Streams(streams)
            , m_Settings(settings) {

            // A reference render writes no file: no capture, no output folder.
            if (m_Settings.PassReferenceOnly) { m_Capture = nullptr; return; }

            CAfxCapture::CaptureType_e captureType;
            switch(m_Settings.CaptureType) {
            case CStreamSettings::CaptureType_e::Rgba:
                captureType = CAfxCapture::CaptureType_Rgba;
                break;
            case CStreamSettings::CaptureType_e::DepthRgb:
                captureType = m_Settings.Depth24 ? CAfxCapture::CaptureType_Depth24 : CAfxCapture::CaptureType_Rgba;
                break;
            default:
                captureType = CAfxCapture::CaptureType_Default;
            };

            auto videoStreamCreator = m_Settings.Settings->CreateOutVideoStreamCreator(
                *this,
                *this,
                m_Streams->m_OutputFpsOverride > 0.0f
                    ? m_Streams->m_OutputFpsOverride : m_Streams->m_StartHostFrameRateValue,
                ""
            );
            m_Capture = new CAfxCapture(videoStreamCreator, captureType);
            videoStreamCreator->Release();
		}

		~CStream() {
            if (!m_Capture) return;
            auto & pRenderPassCommands = g_RenderCommands.EngineThread_GetCommands();
            {
                auto & queue = pRenderPassCommands.AfterPresentOrContextLossReliable;
                CAfxCapture * capture = m_Capture;
                queue.Push([capture](ID3D11DeviceContext * pDeviceContext){
                    capture->ShutDown(pDeviceContext);
                }); 
            }
            {
                auto & queue = pRenderPassCommands.FinalizeReliable;
                CAfxCapture * capture = m_Capture;
                queue.Push([capture](){
                    delete capture;
                }); 
            }            
        }

        virtual bool GetStreamFolder(std::wstring& outFolder) const {
            outFolder = m_Streams->GetTakeDir();
            outFolder.append(L"\\");
            outFolder.append(m_Settings.Folder.empty() ? m_Settings.Name : m_Settings.Folder);
            return true;
        }
        
        virtual advancedfx::StreamCaptureType GetCaptureType() const {
            switch(m_Settings.CaptureType) {
            case CStreamSettings::CaptureType_e::Rgb:
                return advancedfx::StreamCaptureType::Normal;
            case CStreamSettings::CaptureType_e::Rgba:
                return advancedfx::StreamCaptureType::Normal;
            case CStreamSettings::CaptureType_e::DepthRgb:
                if(m_Settings.Depth24) {
                    if(m_Settings.DepthZip) {
                        return advancedfx::StreamCaptureType::Depth24ZIP;
                    } else {
                        return advancedfx::StreamCaptureType::Depth24;
                    }
                } else {
                    return advancedfx::StreamCaptureType::Normal;
                }
                break;
            case CStreamSettings::CaptureType_e::DepthF:
                if(m_Settings.DepthZip) {
                    return advancedfx::StreamCaptureType::DepthFZIP;
                } else {
                    return advancedfx::StreamCaptureType::DepthF;
                }                
                break;            
            }
            return advancedfx::StreamCaptureType::Invalid;
        }

        virtual  advancedfx::CGrowingBufferPoolThreadSafe * GetImageBufferPool() const {
            return &g_ImageBufferPool;
        }

        virtual bool GetFormatBmpNotTga() const {
            return m_Streams->GetFormatBmpNotTga();
        }

        void EngineThread_BeginFrame() const {
            // Setup SceneSystem policies:
            SetupSceneFilterPolicies(m_Settings);

            // Execute before commands:
            if(!m_Settings.BeforeCommands.empty())
                ExecuteCommands(m_Settings.BeforeCommands, true);

            // Setup main clear color override:
            if(m_Settings.ClearOverride) {
                float R = m_Settings.ClearOverrideColor.R;
                float G = m_Settings.ClearOverrideColor.G;
                float B = m_Settings.ClearOverrideColor.B;
                float A = m_Settings.ClearOverrideColor.A;  
                auto & renderPassCommands = g_RenderCommands.EngineThread_GetCommands();              
                renderPassCommands.BeforeClear.Push([R,G,B,A](){
                    g_ClearRenderTargetView_ClearOverride = true;
                    g_ClearRenderTargetView_ClearOverrideColor[0] = R;
                    g_ClearRenderTargetView_ClearOverrideColor[1] = G;
                    g_ClearRenderTargetView_ClearOverrideColor[2] = B;
                    g_ClearRenderTargetView_ClearOverrideColor[3] = A;
                });                
            }

            // Setup beforeUi clear and color:
            float clearColor[4];
            if(WantsClearBeforeUi(clearColor)) {
                float R = clearColor[0];
                float G = clearColor[1];
                float B = clearColor[2];
                float A = clearColor[3];  
                auto & renderPassCommands = g_RenderCommands.EngineThread_GetCommands();              
                renderPassCommands.BeforeUi2.Push([R,G,B,A](ID3D11DeviceContext * pDeviceContext, ID3D11RenderTargetView * pTarget){
                    float clearColor[4] = {R,G,B,A};
                    pDeviceContext->ClearRenderTargetView(pTarget, clearColor);
                });
            }

            // Setup capturing:

            if (m_Settings.PassReferenceOnly) {
                // World Only reference for the Players Only mask of this same logical frame.
                g_RenderCommands.EngineThread_GetCommands().BeforeUi.Push([](ID3D11DeviceContext * pDeviceContext, ID3D11Texture2D * pTexture){
                    AfxRenderPass::StoreWorldReference(pDeviceContext, g_pCurrentDepthStencilView);
                });
                return;
            }

            if(nullptr == m_Capture) return;

            auto & renderPassCommands = g_RenderCommands.EngineThread_GetCommands();
            CAfxCapture * capture = m_Capture;
            CStreamSettings::CaptureType_e captureType = m_Settings.CaptureType;
            bool depthCompositeSmoke = m_Settings.DepthCompositeSmoke;
            bool depth24 = m_Settings.Depth24;
            float depthVal = m_Settings.DepthVal;
            float depthValMax = m_Settings.DepthValMax;
            CStreamSettings::DepthChannels_e depthChannels = m_Settings.DepthChannels;
            CStreamSettings::DepthMode_e depthMode = m_Settings.DepthMode;
            {
                auto &queue = m_Settings.Capture == CStreamSettings::Capture_e::BeforeUi ? renderPassCommands.BeforeUi : renderPassCommands.BeforePresent;
                const bool playersOnlyGreen = m_Settings.PassElements == (int)Filmmaker::VisibleElements::OnlyPlayers;
                if (m_Settings.IsPass()) {
                    Filmmaker::PassConfig pass;
                    pass.type = (Filmmaker::PassType)m_Settings.PassType;
                    pass.elements = (Filmmaker::VisibleElements)m_Settings.PassElements;
                    if (!Filmmaker::PassIsDirectCapture(pass)) {
                        AfxRenderPass::ComposeParams params;
                        params.mode = m_Settings.PassType;
                        params.mask = (int)Filmmaker::PassMaskFor(pass.elements);
                        // The job renders World Only before this (RecordStart's reference stream).
                        params.worldRef = pass.elements == Filmmaker::VisibleElements::OnlyPlayers;
                        float key[4];
                        Filmmaker::RenderPlayersOnlyGreen_KeyColor(key);
                        params.keyIn[0] = key[0]; params.keyIn[1] = key[1]; params.keyIn[2] = key[2];
                        params.keyIn[3] = g_PassKeyTolerance;
                        params.keyOut[0] = m_Settings.PassKeyOut[0];
                        params.keyOut[1] = m_Settings.PassKeyOut[1];
                        params.keyOut[2] = m_Settings.PassKeyOut[2];
                        params.nearUnits = m_Settings.PassDepthNear;
                        params.farUnits = m_Settings.PassDepthFar;
                        if (g_PassDepthDebug && params.mode == (int)Filmmaker::PassType::Depth) params.mode = 4;
                        queue.Push([capture, params](ID3D11DeviceContext * pDeviceContext, ID3D11Texture2D * pTexture) mutable {
                            {
                                AfxFillPassFrame(params);
                                if (Filmmaker::MvmDebugLog_Active()) {
                                    static std::atomic<unsigned> s_projLogs{0};
                                    if (s_projLogs.fetch_add(1, std::memory_order_relaxed) < 6)
                                        Filmmaker::MvmDebugLog_LinefAlways("render.pass.compositor",
                                            "compose mode=%d mask=%d cam=(%.1f %.1f %.1f) fwd=(%.3f %.3f %.3f) reversed=%d depthRange=(%.6f %.6f) hasW2C=%d dsv=%p",
                                            params.mode, params.mask, params.camera[0], params.camera[1], params.camera[2],
                                            params.forward[0], params.forward[1], params.forward[2], params.reversedDepth ? 1 : 0,
                                            params.depthMin, params.depthMax, g_EnvironmentFrame.hasWorldToClip ? 1 : 0,
                                            (void*)g_pCurrentDepthStencilView);
                                }
                            }
                            if (ID3D11Texture2D * composed = AfxRenderPass::Compose(pDeviceContext, pTexture, g_pCurrentDepthStencilView, params))
                                capture->OnBeforeGpuPresent(pDeviceContext, composed, 1.0f, 0.0f);
                            else
                                capture->OnBeforeGpuPresent(pDeviceContext, pTexture, 1.0f, 0.0f); // keeps every stream the same length
                        });
                        auto & after = renderPassCommands.AfterPresent;
                        after.Push([capture](ID3D11DeviceContext * pDeviceContext){
                            capture->OnAfterGpuPresent(pDeviceContext);
                        });
                        return;
                    }
                }
                queue.Push([capture,captureType,depthCompositeSmoke,depth24,depthVal,depthValMax,depthChannels,depthMode,playersOnlyGreen](ID3D11DeviceContext * pDeviceContext, ID3D11Texture2D * pTexture){
                    if (playersOnlyGreen && Filmmaker::MvmDebugLog_Active()) {
                        static std::atomic<unsigned> s_greenCaptureEvents{0};
                        const unsigned event = s_greenCaptureEvents.fetch_add(1, std::memory_order_relaxed);
                        if (event < 8) {
                            ID3D11Resource* currentResource = nullptr;
                            if (g_pCurrentRenderTargetView) g_pCurrentRenderTargetView->GetResource(&currentResource);
                            Filmmaker::MvmDebugLog_LinefAlways("render.playersonlygreen.capture",
                                "ordinal=%d texture=%p currentScene=%p active=%d",
                                g_RenderCommands.RenderThread_PassOrdinal(), (void*)pTexture,
                                (void*)currentResource,
                                Filmmaker::RenderPlayersOnlyGreen_RenderActive() ? 1 : 0);
                            AfxPlayersOnlyGreen_ProbePixel(pDeviceContext, pTexture, "capture");
                            if (currentResource) {
                                ID3D11Texture2D* sceneTexture = nullptr;
                                if (SUCCEEDED(currentResource->QueryInterface(
                                    __uuidof(ID3D11Texture2D), (void**)&sceneTexture)) && sceneTexture) {
                                    AfxPlayersOnlyGreen_ProbePixel(pDeviceContext, sceneTexture, "scene");
                                    sceneTexture->Release();
                                }
                            }
                            if (currentResource) currentResource->Release();
                        }
                    }
                    float zNear = depthVal;
                    float zFar = depthValMax;

                    switch(captureType) {
                    case CStreamSettings::CaptureType_e::DepthRgb:
                    case CStreamSettings::CaptureType_e::DepthF: {
                        ShaderCombo_afx_depth_ps_5_0::AFXD24_e afxD24;
                        switch(depthChannels) {
                        case CStreamSettings::DepthChannels_e::SplitRgb:
                            afxD24 = ShaderCombo_afx_depth_ps_5_0::AFXD24_1;
                            break;
                        case CStreamSettings::DepthChannels_e::Dithered:
                            afxD24 = ShaderCombo_afx_depth_ps_5_0::AFXD24_3;
                            break;
                        case CStreamSettings::DepthChannels_e::Gray:
                        default:
                            afxD24 = ShaderCombo_afx_depth_ps_5_0::AFXD24_0;
                            break;
                        }

                        ShaderCombo_afx_depth_ps_5_0::AFXDEPTHMODE_e afxDepthMode;
                        switch(depthMode) {
                        case CStreamSettings::DepthMode_e::Linear:
                            afxDepthMode = ShaderCombo_afx_depth_ps_5_0::AFXDEPTHMODE_1; 
                            break;
                        case CStreamSettings::DepthMode_e::LogE:
                            afxDepthMode = ShaderCombo_afx_depth_ps_5_0::AFXDEPTHMODE_2; 
                            break;
                        case CStreamSettings::DepthMode_e::PyramidalLinear:
                            afxDepthMode = ShaderCombo_afx_depth_ps_5_0::AFXDEPTHMODE_3; 
                            break;
                        case CStreamSettings::DepthMode_e::PyramidalLogE:
                            afxDepthMode = ShaderCombo_afx_depth_ps_5_0::AFXDEPTHMODE_4; 
                            break;
                        case CStreamSettings::DepthMode_e::Inverse:
                        default:
                                afxDepthMode = ShaderCombo_afx_depth_ps_5_0::AFXDEPTHMODE_0; 
                                break;
                        }

                        g_DepthCompositor.CaptureNormalDepth(pDeviceContext, g_pCurrentDepthStencilView,
                            depthCompositeSmoke,
                            captureType == CStreamSettings::CaptureType_e::DepthF ? CDepthCompositor::DepthTextureType_R32F : CDepthCompositor::DepthTextureType_RGB,
                            afxDepthMode,
                            afxD24,
                            zNear,
                            zFar
                        );
        
                        ID3D11RenderTargetView* pRenderTargetViews[1] = {nullptr};
                        ID3D11DepthStencilView* pDepthStencilView = nullptr;
                        pDeviceContext->OMGetRenderTargets(1, &pRenderTargetViews[0], &pDepthStencilView);
        
                        ID3D11Resource* pRenderTargetViewResource = nullptr;
                        if (pRenderTargetViews[0]) pRenderTargetViews[0]->GetResource(&pRenderTargetViewResource);
        
                        if (ID3D11Texture2D* pTexture = g_DepthCompositor.GetDepthTexture(captureType == CStreamSettings::CaptureType_e::DepthF ? CDepthCompositor::DepthTextureType_R32F : CDepthCompositor::DepthTextureType_RGB)) {
                            capture->OnBeforeGpuPresent(pDeviceContext, pTexture, zFar - zNear, zNear);
                            pTexture->Release();
                        }// else capture->OnBeforeGpuPresent(pDeviceContext, nullptr);
        
                        if (pRenderTargetViewResource) pRenderTargetViewResource->Release();
        
                        if (pDepthStencilView) pDepthStencilView->Release();
                        if (pRenderTargetViews[0]) pRenderTargetViews[0]->Release();
                    } break;
                    default:
                        capture->OnBeforeGpuPresent(pDeviceContext, pTexture, zFar - zNear, zNear);
                        break;
                    }
                });
            }
            {
                auto & queue = renderPassCommands.AfterPresent;
                queue.Push([capture](ID3D11DeviceContext * pDeviceContext){
                    capture->OnAfterGpuPresent(pDeviceContext);
                }); 
            }
        }

        void EngineThread_EndFrame() const {
            // Execute after commands:
            if(!m_Settings.AfterCommands.empty())
                ExecuteCommands(m_Settings.AfterCommands);

            // Put back what the before commands changed, so a stream never leaves its cvar
            // values behind (a preset's "after X 1" would otherwise enable an X the user had off).
            RestoreSavedCvars();

            // Clear SceneSystem policies:
            ClearSceneFliterSystemPolicies();
        } 

        bool WantsClearBeforeUi(float outColor[4]) const {
            if(m_Settings.ClearBeforeUi) {
                outColor[0] = m_Settings.ClearBeforeUiColor.R;
                outColor[1] = m_Settings.ClearBeforeUiColor.G;
                outColor[2] = m_Settings.ClearBeforeUiColor.B;
                outColor[3] = m_Settings.ClearBeforeUiColor.A;
                return true;
            }
            return false;
        }

        bool CanCaptureInMainPass() const {
            return m_Settings.CanCaptureInMainPass();                
        }

        // Read access for the pass-policy schedule builder (RecordStart): the schedule needs the
        // pass-defining fields of each group head, nothing more.
        const CStreamSettings & GetSettings() const { return m_Settings; }

        int CompareRenderPass(const CStream & o) const {
            return m_Settings.CompareRenderPass(o.m_Settings);
        }

    private:
        CAfxStreams * m_Streams;
        CStreamSettings m_Settings;
        CAfxCapture * m_Capture;

        typedef decltype(SOURCESDK::CS2::g_pCVar->FindConVar("", false)) CvarHandle_t;
        struct SavedCvar {
            CvarHandle_t Handle;
            unsigned char Value[sizeof(SOURCESDK::CS2::CVValue_t)];
            bool IsString;
            std::string Text; // strings own heap memory, so they are kept as text, not raw bytes
        };
        mutable std::vector<SavedCvar> m_SavedCvars;

        void RestoreSavedCvars() const {
            for(auto it = m_SavedCvars.rbegin(); it != m_SavedCvars.rend(); it++) {
                if(SOURCESDK::CS2::Cvar_s * p_cvar = SOURCESDK::CS2::g_pCVar->GetCvar(it->Handle.Get())) {
                    SOURCESDK::CS2::CVValue_t oldValue = {};
                    if(it->IsString) {
                        oldValue.m_szValue.Set(p_cvar->m_Value.m_szValue.Get());
                        p_cvar->m_Value.m_szValue.Set(it->Text.c_str());
                    } else {
                        memcpy(&oldValue, &p_cvar->m_Value, sizeof(oldValue));
                        memcpy(&p_cvar->m_Value, it->Value, sizeof(it->Value));
                    }
                    SOURCESDK::CS2::g_pCVar->CallChangeCallback(it->Handle, 0, &p_cvar->m_Value, &oldValue);
                }
            }
            m_SavedCvars.clear();
        }

        void ExecuteCommands(const std::list<std::list<std::string>> & commands, bool saveOriginals = false) const {
            for(auto it = commands.begin(); it != commands.end(); it++) {
                auto & command = *it;
                auto it2 = command.begin();
                if(it2 == command.end()) continue;
                const char * pArg0 = it2->c_str();
                auto cvar_handle = SOURCESDK::CS2::g_pCVar->FindConVar(pArg0, false);
                if(SOURCESDK::CS2::Cvar_s * p_cvar = SOURCESDK::CS2::g_pCVar->GetCvar(cvar_handle.Get())) {
                    const char * pszError = nullptr;
                    const char * pszWrongNumberOfArguments = "Wrong number of arguments";
                    auto & value = p_cvar->m_Value;
                    if(saveOriginals) {
                        bool saved = false;
                        for(auto & s : m_SavedCvars) if(s.Handle.Get() == cvar_handle.Get()) { saved = true; break; }
                        if(!saved) {
                            SavedCvar s = { cvar_handle };
                            s.IsString = p_cvar->m_eVarType == SOURCESDK::CS2::EConVarType_String;
                            if(s.IsString) {
                                const char * text = value.m_szValue.Get();
                                s.Text = text ? text : "";
                            } else memcpy(s.Value, &value, sizeof(s.Value));
                            m_SavedCvars.push_back(s);
                        }
                    }
                    switch(p_cvar->m_eVarType) {
                    case SOURCESDK::CS2::EConVarType_Bool:
                        if(command.size() < 2) pszError = pszWrongNumberOfArguments;
                        else  {
                            it2++;
                            SOURCESDK::CS2::CVValue_t oldValue = {};
                            oldValue.m_bValue = value.m_bValue;
                            value.m_bValue = 0 == strcmp("true", it2->c_str()) || 0 != std::strtol(it2->c_str(),nullptr,10);
                            SOURCESDK::CS2::g_pCVar->CallChangeCallback(cvar_handle, 0, &value, &oldValue);
                        }
                        break;
                    case SOURCESDK::CS2::EConVarType_Int16:
                        if(command.size() < 2) pszError = pszWrongNumberOfArguments;
                        else  {
                            it2++;
                            SOURCESDK::CS2::CVValue_t oldValue = {};
                            oldValue.m_i16Value = value.m_i16Value;                            
                            value.m_i16Value = (int16_t)std::strtol(it2->c_str(),nullptr,10);
                            SOURCESDK::CS2::g_pCVar->CallChangeCallback(cvar_handle, 0, &value, &oldValue);
                        }
                        break;
                    case SOURCESDK::CS2::EConVarType_UInt16:
                        if(command.size() < 2) pszError = pszWrongNumberOfArguments;
                        else  {
                            it2++;
                            SOURCESDK::CS2::CVValue_t oldValue = {};
                            oldValue.m_u16Value = value.m_u16Value;                            
                            value.m_u16Value = (uint16_t)std::strtoul(it2->c_str(),nullptr,10);
                            SOURCESDK::CS2::g_pCVar->CallChangeCallback(cvar_handle, 0, &value, &oldValue);
                        }
                        break;
                    case SOURCESDK::CS2::EConVarType_Int32:
                        if(command.size() < 2) pszError = pszWrongNumberOfArguments;
                        else  {
                            it2++;
                            SOURCESDK::CS2::CVValue_t oldValue = {};
                            oldValue.m_i32Value = value.m_i32Value;                               
                            value.m_i32Value = (int32_t)std::strtol(it2->c_str(),nullptr,10);
                            SOURCESDK::CS2::g_pCVar->CallChangeCallback(cvar_handle, 0, &value, &oldValue);
                        }
                        break;
                    case SOURCESDK::CS2::EConVarType_UInt32:
                        if(command.size() < 2) pszError = pszWrongNumberOfArguments;
                        else  {
                            it2++;
                            SOURCESDK::CS2::CVValue_t oldValue = {};
                            oldValue.m_u32Value = value.m_u32Value;                               
                            value.m_u32Value = (uint32_t)std::strtoul(it2->c_str(),nullptr,10);
                            SOURCESDK::CS2::g_pCVar->CallChangeCallback(cvar_handle, 0, &value, &oldValue);
                        }
                        break;
                    case SOURCESDK::CS2::EConVarType_Int64:
                        if(command.size() < 2) pszError = pszWrongNumberOfArguments;
                        else  {
                            it2++;
                            SOURCESDK::CS2::CVValue_t oldValue = {};
                            oldValue.m_i64Value = value.m_i64Value;                               
                            value.m_i64Value = (int64_t)std::strtoll(it2->c_str(),nullptr,10);
                            SOURCESDK::CS2::g_pCVar->CallChangeCallback(cvar_handle, 0, &value, &oldValue);
                        }
                        break;
                    case SOURCESDK::CS2::EConVarType_UInt64:
                        if(command.size() < 2) pszError = pszWrongNumberOfArguments;
                        else  {
                            it2++;
                            SOURCESDK::CS2::CVValue_t oldValue = {};
                            oldValue.m_u64Value = value.m_u64Value;                               
                            value.m_u64Value = (uint64_t)std::strtoull(it2->c_str(),nullptr,10);
                            SOURCESDK::CS2::g_pCVar->CallChangeCallback(cvar_handle, 0, &value, &oldValue);
                        }
                        break;
                    case SOURCESDK::CS2::EConVarType_Float32:
                        if(command.size() < 2) pszError = pszWrongNumberOfArguments;
                        else  {
                            it2++;
                            SOURCESDK::CS2::CVValue_t oldValue = {};
                            oldValue.m_flValue = value.m_flValue;                               
                            value.m_flValue = std::strtof(it2->c_str(),nullptr);
                            SOURCESDK::CS2::g_pCVar->CallChangeCallback(cvar_handle, 0, &value, &oldValue);
                        }
                        break;                    
                    case SOURCESDK::CS2::EConVarType_Float64:
                        if(command.size() < 2) pszError = pszWrongNumberOfArguments;
                        else  {
                            it2++;
                            SOURCESDK::CS2::CVValue_t oldValue = {};
                            oldValue.m_dbValue = value.m_dbValue;                               
                            value.m_dbValue = std::strtod(it2->c_str(),nullptr);
                            SOURCESDK::CS2::g_pCVar->CallChangeCallback(cvar_handle, 0, &value, &oldValue);
                        }    
                        break;           
                    case SOURCESDK::CS2::EConVarType_String:
                        if(command.size() < 2) pszError = pszWrongNumberOfArguments;
                        else  {
                            it2++;
                            SOURCESDK::CS2::CVValue_t oldValue = {};
                            oldValue.m_szValue.Set(value.m_szValue.Get());
                            value.m_szValue.Set(it2->c_str());
                            SOURCESDK::CS2::g_pCVar->CallChangeCallback(cvar_handle, 0, &value, &oldValue);
                        }    
                        break;           
                    case SOURCESDK::CS2::EConVarType_Color:
                        if(command.size() < 5) pszError = pszWrongNumberOfArguments;
                        else  {
                            it2++; float f1 = std::strtof(it2->c_str(),nullptr);
                            it2++; float f2 = std::strtof(it2->c_str(),nullptr);
                            it2++; float f3 = std::strtof(it2->c_str(),nullptr);
                            it2++; float f4 =std::strtof( it2->c_str(),nullptr);
                            SOURCESDK::CS2::CVValue_t oldValue = {};
                            oldValue.m_clrValue = value.m_clrValue;
                            value.m_clrValue.SetColor(f1,f2,f3,f4);
                            SOURCESDK::CS2::g_pCVar->CallChangeCallback(cvar_handle, 0, &value, &oldValue);
                        }
                        break;                    
                    case SOURCESDK::CS2::EConVarType_Vector2:
                        if(command.size() < 3) pszError = pszWrongNumberOfArguments;
                        else  {
                            it2++; float f1 = std::strtof(it2->c_str(),nullptr);
                            it2++; float f2 = std::strtof(it2->c_str(),nullptr);
                            SOURCESDK::CS2::CVValue_t oldValue = {};
                            oldValue.m_vec2Value = value.m_vec2Value;
                            value.m_vec2Value.x = f1;
                            value.m_vec2Value.y = f2;
                            SOURCESDK::CS2::g_pCVar->CallChangeCallback(cvar_handle, 0, &value, &oldValue);
                        }
                        break;
                    case SOURCESDK::CS2::EConVarType_Vector3:
                        if(command.size() < 4) pszError = pszWrongNumberOfArguments;
                        else  {
                            it2++; float f1 = std::strtof(it2->c_str(),nullptr);
                            it2++; float f2 = std::strtof(it2->c_str(),nullptr);
                            it2++; float f3 = std::strtof(it2->c_str(),nullptr);
                            SOURCESDK::CS2::CVValue_t oldValue = {};
                            oldValue.m_vec3Value = value.m_vec3Value;
                            value.m_vec3Value.x = f1;
                            value.m_vec3Value.y = f2;
                            value.m_vec3Value.z = f3;
                            SOURCESDK::CS2::g_pCVar->CallChangeCallback(cvar_handle, 0, &value, &oldValue);
                        }
                        break;
                    case SOURCESDK::CS2::EConVarType_Vector4:
                        if(command.size() < 5) pszError = pszWrongNumberOfArguments;
                        else  {
                            it2++; float f1 = std::strtof(it2->c_str(),nullptr);
                            it2++; float f2 = std::strtof(it2->c_str(),nullptr);
                            it2++; float f3 = std::strtof(it2->c_str(),nullptr);
                            it2++; float f4 =std::strtof( it2->c_str(),nullptr);
                            SOURCESDK::CS2::CVValue_t oldValue = {};
                            oldValue.m_vec4Value = value.m_vec4Value;
                            value.m_vec4Value.x = f1;
                            value.m_vec4Value.y = f2;
                            value.m_vec4Value.z = f3;
                            value.m_vec4Value.w = f4;
                            SOURCESDK::CS2::g_pCVar->CallChangeCallback(cvar_handle, 0, &value, &oldValue);
                        }
                        break;
                    case SOURCESDK::CS2::EConVarType_Qangle:
                        if(command.size() < 4) pszError = pszWrongNumberOfArguments;
                        else  {
                            it2++; float f1 = std::strtof(it2->c_str(),nullptr);
                            it2++; float f2 = std::strtof(it2->c_str(),nullptr);
                            it2++; float f3 = std::strtof(it2->c_str(),nullptr);
                            SOURCESDK::CS2::CVValue_t oldValue = {};
                            oldValue.m_angValue = value.m_angValue;
                            value.m_angValue.x = f1;
                            value.m_angValue.y = f2;
                            value.m_angValue.z = f3;
                            SOURCESDK::CS2::g_pCVar->CallChangeCallback(cvar_handle, 0, &value, &oldValue);
                        }
                        break;
                    case SOURCESDK::CS2::EConVarType_VectorWS:
                        if(command.size() < 4) pszError = pszWrongNumberOfArguments;
                        else  {
                            it2++; float f1 = std::strtof(it2->c_str(),nullptr);
                            it2++; float f2 = std::strtof(it2->c_str(),nullptr);
                            it2++; float f3 = std::strtof(it2->c_str(),nullptr);
                            SOURCESDK::CS2::CVValue_t oldValue = {};
                            oldValue.m_vecwsValue = value.m_vecwsValue;
                            value.m_vecwsValue.x = f1;
                            value.m_vecwsValue.y = f2;
                            value.m_vecwsValue.z = f3;
                            SOURCESDK::CS2::g_pCVar->CallChangeCallback(cvar_handle, 0, &value, &oldValue);
                        }
                        break;                        
                    default:
                        pszError = "Unknown cvar type";
                        break;
                    }
                    if(pszError){
                        advancedfx::Warning("AFXWARNING: \"%s\" cvar to be set has the following problem: %s.", pArg0,pszError);
                    }
                } else {
                   SOURCESDK::CS2::ConCommandHandle cmd_handle = SOURCESDK::CS2::g_pCVar->FindCommand(pArg0, false );
                    if(cmd_handle.IsValid()) {
                        std::vector<const char *> vecArgs(command.size());
                        size_t i = 0;
                        while(it2 != command.end()) {
                            vecArgs[i] = it2->c_str();
                            it2++;
                            i++;
                        }
                        SOURCESDK::CS2::g_pCVar->DispatchConCommand(cmd_handle, SOURCESDK::CS2::CCommandContext(SOURCESDK::CS2::CT_FIRST_SPLITSCREEN_CLIENT,0), SOURCESDK::CS2::CCommand(vecArgs.size(),vecArgs.data()));
                    } else {
                        advancedfx::Warning("AFXWARNING: \"%s\" to be set / executed is not a command or cvar.", pArg0);
                    }
                }
            }
        }
	};

    struct RenderPassCompare {
          bool operator() (const CStream & lhs, const CStream & rhs) const {
            return lhs.CompareRenderPass(rhs) < 0;
        }
    };

    std::list<CStream> m_RecordingMainPass;
    std::multiset<CStream,RenderPassCompare> m_RecordingExtraPasses;
    std::multiset<CStream,RenderPassCompare>::iterator m_RecordingExtraPassesIterator;
    // Distinct extra-pass groups begun this capture frame; ordinal = 1 + index. Reset when the
    // main pass begins, so a frame with fewer groups can never inherit a stale count.
    int m_ExtraPassGroupCounter = 0;

    std::map<std::string, CStreamSettings> m_Streams;

    bool m_Shutdown = false;
    advancedfx::StreamCaptureType m_StreamCaptureType = advancedfx::StreamCaptureType::Normal;
    bool m_FormatBmpAndNotTga = false;
    bool m_StartMovieWav = true;
    bool m_OverrideFps = false;
    float m_OverrideFpsValue = 60.0;
    std::string m_RecordName = "untitled_rec";
    bool m_RecordingCapturesAfterUi = false;
    
	class CRecordScreen {
	public:
		bool Enabled;
		advancedfx::CRecordingSettings* Settings;

		CRecordScreen(bool enabled, advancedfx::CRecordingSettings* settings)
			: Enabled(enabled)
			, Settings(settings)
		{
			settings->AddRef();
		}

		CRecordScreen(const CRecordScreen& other)
		: Enabled(other.Enabled)
		, Settings(other.Settings) {
			Settings->AddRef();
		}

		~CRecordScreen() {
			Settings->Release();
		}
	};
	CRecordScreen* m_RecordScreen;

    bool m_Recording = false;
    bool m_RecordTakeSubfolder = true; // see AfxStreams_SetRecordTakeSubfolder
	std::atomic<int> m_RecordedSourceFrameCount{0};
    std::wstring m_TakeDir;
    bool m_StartMovieWavUsed = false;
    float m_StartHostFrameRateValue = 60.0;
    // Output/mux framerate override for stream creators (0 = use m_StartHostFrameRateValue).
    // The Filmmaker render job sets this to the PLAYBACK fps: under the timescale dial the
    // recorder samples at fps/timescale (host_framerate lock), but the encoded file must play
    // at the output fps or the slow motion collapses back to real time in the container.
    float m_OutputFpsOverride = 0.0f;
    
    bool m_UsedHostFramerRateValue = false;
    float m_OldValue_host_framerate;
    bool m_OldValue_r_always_render_all_windows;
    int m_OldValue_engine_no_focus_sleep;
    bool m_OldValue_r_wait_on_present;

    bool m_AutoForceFullReSmoke = false;

    bool m_CompositeSmoke = false;

    bool m_Restore_smoke_volume_lod_ratio_change = false;
    float m_Old_smoke_volume_lod_ratio_change = 0.6;

    bool m_Restore_r_csgo_mboit_force_mixed_resolution = false;
    bool m_Old_r_csgo_mboit_force_mixed_resolution = false;

    bool Console_CheckStreamName(char const * value)
    {
        if(StringIsEmpty(value))
        {
            advancedfx::Warning("AFXERROR: Stream name can not be empty.\n");
            return false;
        }
        if(!StringIsAlNum(value))
        {
            advancedfx::Warning("AFXERROR: Stream name must be alphanumeric.\n");
            return false;
        }

        // Check if name is unique:
        if(m_Streams.find(value) != m_Streams.end())
        {
            advancedfx::Warning("AFXERROR: Stream name must be unique, \"%s\" is already in use.\n", value);
            return false;
        }

        return true;
    }

    void EngineThread_Suppress_Present() {
        auto & pRenderPassCommands = g_RenderCommands.EngineThread_GetCommands();
        {
            auto & queue = pRenderPassCommands.BeforePresent;
            CAfxCapture * capture = g_ActiveCapture;
            queue.Push([capture](ID3D11DeviceContext * pDeviceContext, ID3D11Texture2D * pTexture){
                g_Present_Suppress = true;
            }); 
        }
        {
            auto & queue = pRenderPassCommands.AfterPresent;
            CAfxCapture * capture = g_ActiveCapture;
            queue.Push([capture](ID3D11DeviceContext * pDeviceContext){
                g_Present_Suppress = false;
            }); 
        }
    }

    void EngineThread_Expect_Present() {
        auto & pRenderPassCommands = g_RenderCommands.EngineThread_GetCommands();
        {
            auto & queue = pRenderPassCommands.BeforePresent;
            CAfxCapture * capture = g_ActiveCapture;
            queue.Push([capture](ID3D11DeviceContext * pDeviceContext, ID3D11Texture2D * pTexture){
                g_bExpectPresent = true;
            }); 
        }
        {
            auto & queue = pRenderPassCommands.AfterPresent;
            CAfxCapture * capture = g_ActiveCapture;
            queue.Push([capture](ID3D11DeviceContext * pDeviceContext){
                g_bExpectPresent = false;
            }); 
        }        
    }
} g_AfxStreams;

void AfxStreams_ShutDown() {
    g_AfxStreams.ShutDown();
}

bool g_bEngine_Prepared = false;

bool __fastcall New_CRenderDeviceBase_Present(
    void * This, void * Rdx, void * R8d, void * R9d, void * Stack0, void * Stack1, void * Stack2, void * Stack3, void * Stack4) {

    bool result = g_Old_CRenderDeviceBase_Present(This, Rdx, R8d, R9d, Stack0, Stack1, Stack2, Stack3, Stack4);

    g_bEngine_Prepared = false;

    return result;
}

void CAfxStreams::Console_RecordScreen(advancedfx::ICommandArgs* args) {
	int argC = args->ArgC();
	char const* arg0 = args->ArgV(0);

	if (2 <= argC)
	{
		char const* arg1 = args->ArgV(1);
		if (0 == _stricmp(arg1, "enabled")) {
			if (3 <= argC) {
				m_RecordScreen->Enabled = 0 != atoi(args->ArgV(2));
				return;
			}

			advancedfx::Message(
				"%s enabled 0|1 - Disable (0, default) or enable (1) game screen recording.\n"
				"Current value: %i\n"
				, arg0
				, (m_RecordScreen->Enabled?1:0)
			);
			return;
		}
		if (0 == _stricmp(arg1, "settings")) {
			if (3 <= argC)
			{
				char const* arg2 = args->ArgV(2);

				if (advancedfx::CRecordingSettings* settings = advancedfx::CRecordingSettings::GetByName(arg2))
				{
					settings->AddRef();
					m_RecordScreen->Settings->Release();
					m_RecordScreen->Settings = settings;
				}
				else
				{
					advancedfx::Warning("AFXERROR: There is no recording setting named %s\n", arg2);
				}

				return;
			}

			advancedfx::Message(
				"%s settings <name> - Set recording settings to use from mirv_streams settings.\n"
				"Current value: %s\n"
				, arg0
				, m_RecordScreen->Settings->GetName()
			);

			return;
		}
	}

	advancedfx::Message(
		"%s enabled [...] - Enables / disables screen recording.\n"
		"%s settings [...] - Controls recording settings.\n"
		, arg0
		, arg0
	);
}

void CAfxStreams::Console_Add(advancedfx::ICommandArgs* args) {
	int argC = args->ArgC();
	char const* arg0 = args->ArgV(0);

	if (3 <= argC)
	{
        char const* arg1 = args->ArgV(1);
        char const* arg2 = args->ArgV(2);

        CStreamSettings settings(advancedfx::CRecordingSettings::GetDefault());

        if(0 == _stricmp(arg1,"normal")) {
        } else if(0 == _stricmp(arg1,"hudBlack")) {
            settings.ClearBeforeUiColor.R = 0.0f;
            settings.ClearBeforeUiColor.G = 0.0f;
            settings.ClearBeforeUiColor.B = 0.0f;
            settings.ClearBeforeUiColor.A = 0.0f;
            settings.ClearBeforeUi = true;
        } else if(0 == _stricmp(arg1,"hudWhite")) {
            settings.ClearBeforeUiColor.R = 1.0f;
            settings.ClearBeforeUiColor.G = 1.0f;
            settings.ClearBeforeUiColor.B = 1.0f;
            settings.ClearBeforeUiColor.A = 0.0f;
            settings.ClearBeforeUi = true;
        } else if(0 == _stricmp(arg1,"depth")) {
            settings.Capture = CStreamSettings::Capture_e::BeforeUi;
            settings.CaptureType = CStreamSettings::CaptureType_e::DepthRgb;
            // Suggested defaults by Riki:
            settings.DepthVal = 4096;
            settings.DepthValMax = 0;
            settings.DepthChannels = CStreamSettings::DepthChannels_e::Dithered;
            settings.DepthMode = CStreamSettings::DepthMode_e::PyramidalLinear;
        } else if(0 == _stricmp(arg1,"world")) {
            settings.Capture = CStreamSettings::Capture_e::BeforeUi;
            settings.ViewModelAction = CStreamSettings::Action::NoDraw;
            settings.ParticlesAction = CStreamSettings::Action::NoDraw;
            settings.FirstPersonLegsAction = CStreamSettings::Action::NoDraw;
            settings.ShellsAction = CStreamSettings::Action::NoDraw;
            settings.WeaponsAction = CStreamSettings::Action::NoDraw;
            settings.PlayersAction = CStreamSettings::Action::NoDraw;
            settings.SmokeAction = CStreamSettings::Action::NoDraw;
            settings.OverlaysAction = CStreamSettings::Action::NoDraw;          
        } else if(0 == _stricmp(arg1,"playersMatte")) {
            settings.Capture = CStreamSettings::Capture_e::BeforeUi;
            settings.CaptureType = CStreamSettings::CaptureType_e::Rgba;
            settings.ViewModelAction = CStreamSettings::Action::NoDraw;
            settings.ParticlesAction = CStreamSettings::Action::NoDraw;
            settings.ShellsAction = CStreamSettings::Action::ZOnly;
            settings.WeaponsAction = CStreamSettings::Action::ZOnly;
            settings.WorldAction = CStreamSettings::Action::ZOnly;
            settings.SkyAction = CStreamSettings::Action::ZOnly;
            settings.SmokeAction = CStreamSettings::Action::NoDraw;
            settings.OverlaysAction = CStreamSettings::Action::NoDraw;
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_overlays");
                command.emplace_back("0");
                settings.BeforeCommands.emplace_back(command);
            }
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_decals");
                command.emplace_back("0");
                settings.BeforeCommands.emplace_back(command);
            }
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_overlays");
                command.emplace_back("1");
                settings.AfterCommands.emplace_back(command);
            }
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_decals");
                command.emplace_back("1");
                settings.AfterCommands.emplace_back(command);
            }
        } else if(0 == _stricmp(arg1,"weaponsMatte")) {
            settings.Capture = CStreamSettings::Capture_e::BeforeUi;
            settings.CaptureType = CStreamSettings::CaptureType_e::Rgba;
            settings.ViewModelAction = CStreamSettings::Action::NoDraw;
            settings.ParticlesAction = CStreamSettings::Action::NoDraw;
            settings.FirstPersonLegsAction = CStreamSettings::Action::NoDraw;
            settings.ShellsAction = CStreamSettings::Action::ZOnly;
            settings.PlayersAction = CStreamSettings::Action::ZOnly;
            settings.WorldAction = CStreamSettings::Action::ZOnly;
            settings.SkyAction = CStreamSettings::Action::ZOnly;
            settings.SmokeAction = CStreamSettings::Action::NoDraw;
            settings.OverlaysAction = CStreamSettings::Action::NoDraw;
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_overlays");
                command.emplace_back("0");
                settings.BeforeCommands.emplace_back(command);
            }
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_decals");
                command.emplace_back("0");
                settings.BeforeCommands.emplace_back(command);
            }
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_overlays");
                command.emplace_back("1");
                settings.AfterCommands.emplace_back(command);
            }
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_decals");
                command.emplace_back("1");
                settings.AfterCommands.emplace_back(command);
            }
        } else if(0 == _stricmp(arg1,"viewModelMatte")) {
            settings.Capture = CStreamSettings::Capture_e::BeforeUi;
            settings.CaptureType = CStreamSettings::CaptureType_e::Rgba;
            settings.ParticlesAction = CStreamSettings::Action::NoDraw;
            settings.FirstPersonLegsAction = CStreamSettings::Action::NoDraw;
            settings.WeaponsAction = CStreamSettings::Action::NoDraw;
            settings.PlayersAction = CStreamSettings::Action::NoDraw;
            settings.WorldAction = CStreamSettings::Action::NoDraw;
            settings.SkyAction = CStreamSettings::Action::NoDraw;
            settings.SmokeAction = CStreamSettings::Action::NoDraw;
            settings.OverlaysAction = CStreamSettings::Action::NoDraw;
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_overlays");
                command.emplace_back("0");
                settings.BeforeCommands.emplace_back(command);
            }
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_decals");
                command.emplace_back("0");
                settings.BeforeCommands.emplace_back(command);
            }
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_overlays");
                command.emplace_back("1");
                settings.AfterCommands.emplace_back(command);
            }
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_decals");
                command.emplace_back("1");
                settings.AfterCommands.emplace_back(command);
            }
        } else if(0 == _stricmp(arg1,"particlesBlack")) {
            settings.ClearOverrideColor.R = 0.0f;
            settings.ClearOverrideColor.G = 0.0f;
            settings.ClearOverrideColor.B = 0.0f;
            settings.ClearOverrideColor.A = 1.0f;
            settings.ClearOverride = true;
            settings.Capture = CStreamSettings::Capture_e::BeforeUi;
            settings.CaptureType = CStreamSettings::CaptureType_e::Rgba;
            settings.ViewModelAction = CStreamSettings::Action::ZOnly;
            settings.FirstPersonLegsAction = CStreamSettings::Action::ZOnly;
            settings.ShellsAction = CStreamSettings::Action::ZOnly;
            settings.WeaponsAction = CStreamSettings::Action::ZOnly;
            settings.PlayersAction = CStreamSettings::Action::ZOnly;
            settings.WorldAction = CStreamSettings::Action::ZOnly;
            settings.SkyAction = CStreamSettings::Action::ZOnly;
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_overlays");
                command.emplace_back("0");
                settings.BeforeCommands.emplace_back(command);
            }
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_decals");
                command.emplace_back("0");
                settings.BeforeCommands.emplace_back(command);
            }
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_overlays");
                command.emplace_back("1");
                settings.AfterCommands.emplace_back(command);
            }
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_decals");
                command.emplace_back("1");
                settings.AfterCommands.emplace_back(command);
            }
        } else if(0 == _stricmp(arg1,"particlesWhite")) {
            settings.ClearOverrideColor.R = 1.0f;
            settings.ClearOverrideColor.G = 1.0f;
            settings.ClearOverrideColor.B = 1.0f;
            settings.ClearOverrideColor.A = 1.0f;
            settings.ClearOverride = true;
            settings.Capture = CStreamSettings::Capture_e::BeforeUi;
            settings.CaptureType = CStreamSettings::CaptureType_e::Rgba;
            settings.ViewModelAction = CStreamSettings::Action::ZOnly;
            settings.FirstPersonLegsAction = CStreamSettings::Action::ZOnly;
            settings.ShellsAction = CStreamSettings::Action::ZOnly;
            settings.WeaponsAction = CStreamSettings::Action::ZOnly;
            settings.PlayersAction = CStreamSettings::Action::ZOnly;
            settings.WorldAction = CStreamSettings::Action::ZOnly;
            settings.SkyAction = CStreamSettings::Action::ZOnly;
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_overlays");
                command.emplace_back("0");
                settings.BeforeCommands.emplace_back(command);
            }
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_decals");
                command.emplace_back("0");
                settings.BeforeCommands.emplace_back(command);
            }
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_overlays");
                command.emplace_back("1");
                settings.AfterCommands.emplace_back(command);
            }
            {
                std::list<std::string> command;
                command.emplace_back("r_csgo_render_decals");
                command.emplace_back("1");
                settings.AfterCommands.emplace_back(command);
            }
        } else {
            advancedfx::Warning("AFXERROR: \"%s\" is not a valid stream template.\n", arg1);
            return;
        }
        
        if(!Console_CheckStreamName(arg2)) return;

        if (!UTF8StringToWideString(arg2, settings.Name))
        {
            advancedfx::Warning("AFXERROR: Could not convert \"%s\" from UTF8 to wide string.\n", arg2);
            return;
        }

        auto it = m_Streams.begin();
        if(it != m_Streams.end()) {
            // Copy globally shared settings from first stream:
            settings.AutoForceFullResSmoke = it->second.AutoForceFullResSmoke;
        }

        m_Streams.emplace(arg2, settings);
        return;
	}

	advancedfx::Message(
		"%s normal|depth|hudBlack|hudWhite|world|playersMatte|weaponsMatte|viewModelMatte|particlesBlack|particlesWhite <sUniqueStreamName> - Adds a stream of given type.\n"
		, arg0
	);
}

void CAfxStreams::Console_Edit_RenderCommands(std::list<std::list<std::string>> & commands, advancedfx::ICommandArgs* args) {
 	int argC = args->ArgC();
	char const* arg0 = args->ArgV(0);
    
    if(2 <= argC) {
        char const* arg1 = args->ArgV(1);
        if(0 == strcmp("add", arg1))
        {
            if(3 <= argC) {
                std::list<std::string> command;
                for(int i = 2; i < argC; i++) {
                    command.emplace_back(args->ArgV(i));
                }
                commands.emplace_back(command);
                return;
            }
            advancedfx::Message(
                "%s add <sCommandOrCvar> (<sArgument>)*\n"
                , arg0
            );
            return;
        }
        else if(0 == strcmp("print",arg1)) {
            int index = 0;
            for(auto it = commands.begin(); it != commands.end(); it++){
                auto & command = *it;
                advancedfx::Message("%i:", index);
                for(auto it2 = command.begin(); it2 != command.end(); it2++){
                    advancedfx::Message(" \"%s\"", it2->c_str());                    
                }
                advancedfx::Message("\n");
                index++;
            }
            return;
        }
        else if(0 == strcmp("clear",arg1)) {
            commands.clear();
            return;
        }
    }
    
	advancedfx::Message(
		"%s add [...] - Adds a command with arguments to the list.\n"
		"%s print - Prints the command list.\n"
		"%s clear - Clears the command list.\n"
		, arg0
		, arg0
		, arg0
	);
}

namespace {

// Console vocabulary for the two Source 2 pass levers that stand in for Source 1's baseFx material
// actions. CStreamSettings deliberately stores both as plain ints so the generic recorder settings
// do not have to include the SceneSystem / material-override headers; the mapping lives here, next
// to the only code that has to name them.
struct CTokenValue { const char* token; int value; };


} // namespace
const char * StreamSettingsActionToString(CStreamSettings::Action value) {
    switch(value) {
    case CStreamSettings::Action::Draw:
        return "draw";
    case CStreamSettings::Action::NoDraw:
        return "noDraw";
    case CStreamSettings::Action::ZOnly:
        return "zOnly";
    }
    return "(unknown)";
}

bool AssignStreamSettingsAction(CStreamSettings::Action &action, const char * value) {
    if(0 == _stricmp(value,"draw")) {
        action = CStreamSettings::Action::Draw;
        return true;
    }
    if(0 == _stricmp(value,"noDraw")) {
        action = CStreamSettings::Action::NoDraw;
        return true;
    }
    if(0 == _stricmp(value,"zOnly")) {
        action = CStreamSettings::Action::ZOnly;
        return true;
    }
    return false;
}

void StreamSettingsActionSubCommand(CStreamSettings::Action &action, advancedfx::ICommandArgs * args) {
    int argC = args->ArgC();
    const char * cmd0 = args->ArgV(0);
    
    if(2 <= argC) {
        const char * cmd1 = args->ArgV(1);
        if(AssignStreamSettingsAction(action, cmd1))
            return;
    }
    
    advancedfx::Message(
        "%s draw|noDraw|zOnly\n"
        "Current value: %s\n"
        , cmd0, StreamSettingsActionToString(action));    
}

void CAfxStreams::Console_Edit(advancedfx::ICommandArgs* args) {
	int argC = args->ArgC();
	char const* arg0 = args->ArgV(0);

    if(2 <= argC) {
        char const* arg1 = args->ArgV(1);

        auto it = m_Streams.find(arg1);

        if(it == m_Streams.end()) {
            advancedfx::Warning("AFXERROR: No stream named \"%s\" exists.\n", arg1);
            return;            
        }

        auto &stream = it->second;

        if(3 <= argC) {
            char const* arg2 = args->ArgV(2);

            if(0 == _stricmp("record", arg2)) {
                if(4 <= argC) {
                    stream.Record = 0 != atoi(args->ArgV(3));
                    return;
                }

                advancedfx::Message(
                    "%s %s record 0|1 - Whether to record (1) or not (0).\n"
                    "Current value: %i\n"
                    , arg0, arg1
                    , stream.Record ? 1 : 0
                );
                return;
            } else if(0 == _stricmp("capture", arg2)) {
                if(4 <= argC) {
                    char const* arg3 = args->ArgV(3);

                    if(0 == _stricmp("beforePresent", arg3)) {
                        stream.Capture = CStreamSettings::Capture_e::BeforePresent;
                        return;
                    } else if(0 == _stricmp("beforeUI", arg3)) {
                        stream.Capture = CStreamSettings::Capture_e::BeforeUi;
                        return;
                    }
                }

                const char * currentValue = "[unknown]";
                switch(stream.Capture) {
                case CStreamSettings::Capture_e::BeforePresent:
                    currentValue ="beforePresent";
                    break;
                    case CStreamSettings::Capture_e::BeforeUi:
                    currentValue ="beforeUi";
                    break;
                }

                advancedfx::Message(
                    "%s %s capture beforePresent|beforeUi\n"
                    "\tbeforePresent - Capture the game presents on screen.\n"
                    "\tbeforeUi - Capture before Panorama UI is drawn.\n"
                    "Current value: %s\n"
                    , arg0, arg1
                    , currentValue
                ); 
                return;                 
            } else if (0 == _stricmp("settings", arg2)) {
                if (4 <= argC)
                {
                    char const* arg3 = args->ArgV(3);
    
                    if (advancedfx::CRecordingSettings* settings = advancedfx::CRecordingSettings::GetByName(arg3))
                    {
                        settings->AddRef();
                        stream.Settings->Release();
                        stream.Settings = settings;
                    }
                    else
                    {
                        advancedfx::Warning("AFXERROR: There is no recording setting named %s\n", arg3);
                    }
    
                    return;
                }
    
                advancedfx::Message(
                    "%s settings <name> - Set recording settings to use from mirv_streams settings.\n"
                    "Current value: %s\n"
                    , arg0
                    , stream.Settings->GetName()
                );
    
                return;
            } else if(0 == _stricmp("captureType", arg2)) {
                if(4 <= argC) {
                    char const* arg3 = args->ArgV(3);

                    if(0 == _stricmp("rgb", arg3)) {
                        stream.CaptureType = CStreamSettings::CaptureType_e::Rgb;
                        return;
                    } else if(0 == _stricmp("rgba", arg3)) {
                        stream.CaptureType = CStreamSettings::CaptureType_e::Rgba;
                        return;
                    } else if(0 == _stricmp("depthRgb", arg3)) {
                        stream.CaptureType = CStreamSettings::CaptureType_e::DepthRgb;
                        stream.Depth24 = false;
                        return;
                    } else if(0 == _stricmp("depth24", arg3)) {
                        stream.CaptureType = CStreamSettings::CaptureType_e::DepthRgb;
                        stream.Depth24 = true;
                        stream.DepthZip = false;
                        return;
                    } else if(0 == _stricmp("depth24ZIP", arg3)) {
                        // Was advertised by the help text and printable as a current value, but had
                        // no parse branch: the command silently fell through to printing help.
                        stream.CaptureType = CStreamSettings::CaptureType_e::DepthRgb;
                        stream.Depth24 = true;
                        stream.DepthZip = true;
                        return;
                    } else if(0 == _stricmp("depthF", arg3)) {
                        stream.CaptureType = CStreamSettings::CaptureType_e::DepthF;
                        stream.DepthZip = false;
                        return;
                    } else if(0 == _stricmp("depthFZIP", arg3)) {
                        stream.CaptureType = CStreamSettings::CaptureType_e::DepthF;
                        stream.DepthZip = true;
                        return;
                    }
                }

                const char * currentValue = "[unknown]";
                switch(stream.CaptureType) {
                case CStreamSettings::CaptureType_e::Rgb:
                    currentValue ="rgb";
                    break;
                case CStreamSettings::CaptureType_e::Rgba:
                    currentValue ="rgba";
                    break;
                case CStreamSettings::CaptureType_e::DepthRgb:
                    if(stream.Depth24) {
                        if(stream.DepthZip) {
                            currentValue = "depth24ZIP";
                        } else {
                            currentValue = "depth24";
                        }
                    } else {
                        currentValue = "depthRgb";
                    }
                    break;
                case CStreamSettings::CaptureType_e::DepthF:
                    if(stream.DepthZip) {
                        currentValue = "depthFZIP";
                    } else {
                        currentValue = "depthF";
                    }                
                    break;
                }

                advancedfx::Message(
                    "%s %s captureType rgb|rgba|depthRgb|depth24|depth24ZIP|depthF|depthFZIP\n"
                    "\trgb - 3 channels (RGB).\n"
                    "\trgba - 4 channels (RGBA).\n"
                    "\tdepthRgb - Capture depth with 3 channels (RGB).\n"
                    "\tdepth24 - Capture depth with 3 channels (RGB) and tansform to OpenEXR depth (not recommended).\n"
                    "\tdepth24ZIP - Capture depth with 3 channels (RGB) and tansform to compressed OpenEXR depth (not recommended).\n"
                    "\tdepthF - Capture depth with 1 channel to OpenEXR depth.\n"
                    "\tdepthFZIP - Capture depth with 1 channel to compressed OpenEXR depth.\n"
                    "Current value: %s\n"
                    , arg0, arg1
                    , currentValue
                ); 
                return;            
            } else if(0 == _stricmp("depthCompositeSmoke", arg2)) {
                if(4 <= argC) {
                    stream.DepthCompositeSmoke = 0 != atoi(args->ArgV(3));
                    return;
                }

                advancedfx::Message(
                    "%s %s depthCompositeSmoke 0|1 - Whether to composite smoke depth (1) or not (0).\n"
                    "Current value: %i\n"
                    , arg0, arg1
                    , stream.DepthCompositeSmoke ? 1 : 0
                );
                return;
            } else if(0 == _stricmp("depthVal", arg2)) {
                if(4 <= argC) {
                    stream.DepthVal = atof(args->ArgV(3));
                    return;
                }

                advancedfx::Message(
                    "%s %s depthVal <fValue>\n"
                    "Current value: %f\n"
                    , arg0, arg1
                    , stream.DepthVal
                );
                return;
            } else if(0 == _stricmp("depthValMax", arg2)) {
                if(4 <= argC) {
                    stream.DepthValMax = atof(args->ArgV(3));
                    return;
                }

                advancedfx::Message(
                    "%s %s depthValMax <fValue>\n"
                    "Current value: %f\n"
                    , arg0, arg1
                    , stream.DepthValMax
                );
                return;
            } else if(0 == _stricmp("depthChannels", arg2)) {
                if(4 <= argC) {
                    char const* arg3 = args->ArgV(3);

                    if(0 == _stricmp("gray", arg3)) {
                        stream.DepthChannels = CStreamSettings::DepthChannels_e::Gray;
                        return;
                    } else if(0 == _stricmp("splitRgb", arg3)) {
                        stream.DepthChannels = CStreamSettings::DepthChannels_e::SplitRgb;
                        return;
                    } else if(0 == _stricmp("dithered", arg3)) {
                        stream.DepthChannels = CStreamSettings::DepthChannels_e::Dithered;
                        return;
                    }
                }

                const char * currentValue = "[unknown]";
                switch(stream.DepthChannels) {
                case CStreamSettings::DepthChannels_e::Gray:
                    currentValue ="gray";
                    break;
                case CStreamSettings::DepthChannels_e::SplitRgb:
                    currentValue ="splitRgb";
                    break;
                case CStreamSettings::DepthChannels_e::Dithered:
                    currentValue ="dithered";
                    break;
                }

                advancedfx::Message(
                    "%s %s depthChannels gray|splitRgb|dithered\n"
                    "\tgray - Set all 3 channels (RGB) to the same depth value.\n"
                    "\tsplitRgb - Encode depth into 3 channels (RGB).\n"
                    "\tdithered - Dither the depth value into 3 channels (RGB) (similar to https://ReShade.me DrawDepth, reduces perceived bading effects).\n"
                    "Current value: %s\n"
                    , arg0, arg1
                    , currentValue
                ); 
                return;
            } else if(0 == _stricmp("depthMode", arg2)) {
                if(4 <= argC) {
                    char const* arg3 = args->ArgV(3);

                    if(0 == _stricmp("inverse", arg3)) {
                        stream.DepthMode = CStreamSettings::DepthMode_e::Inverse;
                        return;
                    } else if(0 == _stricmp("linear", arg3)) {
                        stream.DepthMode = CStreamSettings::DepthMode_e::Linear;
                        return;
                    } else if(0 == _stricmp("logE", arg3) || 0 == _stricmp("log", arg3)) {
                        stream.DepthMode = CStreamSettings::DepthMode_e::LogE;
                        return;
                    } else if(0 == _stricmp("pyramidalLinear", arg3)) {
                        stream.DepthMode = CStreamSettings::DepthMode_e::PyramidalLinear;
                        return;
                    } else if(0 == _stricmp("pyramidalLogE", arg3) || 0 == _stricmp("pyramidalLog", arg3)) {
                        stream.DepthMode = CStreamSettings::DepthMode_e::PyramidalLogE;
                        return;
                    }
                }

                const char * currentValue = "[unknown]";
                switch(stream.DepthMode) {
                case CStreamSettings::DepthMode_e::Inverse:
                    currentValue ="inverse";
                    break;
                case CStreamSettings::DepthMode_e::Linear:
                    currentValue ="linear";
                    break;
                case CStreamSettings::DepthMode_e::LogE:
                    currentValue ="logE";
                    break;
                    case CStreamSettings::DepthMode_e::PyramidalLinear:
                    currentValue ="pyramidalLinear";
                    break;
                    case CStreamSettings::DepthMode_e::PyramidalLogE:
                    currentValue ="pyramidalLogE";
                    break;
                }

                advancedfx::Message(
                    "%s %s depthMode inverse|linear|logE|pyramidalLinear|pyramidalLogE\n"
                    "\tinverse - Inversed like the game uses.\n"
                    "\tlinear - Linear depth with spherical correction.\n"
                    "\tlogE - Logarithmic depth with spherical correction.\n"
                    "\tpyramidalLinear - Linear depth without spherical correction.\n"
                    "\tpyramidalLogE - Logarithmic depth without spherical correction.\n"
                    "Current value: %s\n"
                    , arg0, arg1
                    , currentValue
                ); 
                return;
            } else if(0 == _stricmp("clear", arg2)) {
                if(4 <= argC) {
                    if(4 == argC) {
                        if(0 == _stricmp("default", args->ArgV(3))) {
                            it->second.ClearOverride = false;
                            return;
                        }
                    } else if(7 == argC) {
                        bool bChanged = false;
                        float r = atof(args->ArgV(3));
                        float g = atof(args->ArgV(4));
                        float b = atof(args->ArgV(5));
                        float a = atof(args->ArgV(6));
                        it->second.ClearOverride = true;
                        it->second.ClearOverrideColor.R = r;
                        it->second.ClearOverrideColor.G = g;
                        it->second.ClearOverrideColor.B = b;
                        it->second.ClearOverrideColor.A = a;
                        return;
                    }
                }

                advancedfx::Message(
                    "%s %s clear default|(<fRed> <fGreen> <fBlue> <fAlpha>) - If to override main clear and in which color (floating point values in range [0.0, 1.0]).\n"
                    , arg0, arg1
                );
                if(!stream.ClearOverride) advancedfx::Message(
                    "Current value: none\n"
                ); else advancedfx::Message(
                        "Current value: %f %f %f %f\n"
                        , stream.ClearOverrideColor.R
                        , stream.ClearOverrideColor.G
                        , stream.ClearOverrideColor.B
                        , stream.ClearOverrideColor.A
                );
                return;
            } else if(0 == _stricmp("clearBeforeUI", arg2)) {
                if(4 <= argC) {
                    if(4 == argC) {
                        if(0 == _stricmp("none", args->ArgV(3))) {
                            it->second.ClearBeforeUi = false;
                            return;
                        }
                    } else if(7 == argC) {
                        bool bChanged = false;
                        float r = atof(args->ArgV(3));
                        float g = atof(args->ArgV(4));
                        float b = atof(args->ArgV(5));
                        float a = atof(args->ArgV(6));
                        it->second.ClearBeforeUi = true;
                        it->second.ClearBeforeUiColor.R = r;
                        it->second.ClearBeforeUiColor.G = g;
                        it->second.ClearBeforeUiColor.B = b;
                        it->second.ClearBeforeUiColor.A = a;
                        return;
                    }
                }

                advancedfx::Message(
                    "%s %s clearBeforeUI none|(<fRed> <fGreen> <fBlue> <fAlpha>) - Whether or not to clear (none, default) or in which color (floating point values in range [0.0, 1.0]).\n"
                    , arg0, arg1
                );
                if(!stream.ClearBeforeUi) advancedfx::Message(
                    "Current value: none\n"
                ); else advancedfx::Message(
                        "Current value: %f %f %f %f\n"
                        , stream.ClearBeforeUiColor.R
                        , stream.ClearBeforeUiColor.G
                        , stream.ClearBeforeUiColor.B
                        , stream.ClearBeforeUiColor.A
                );
                return;
            } else if(0 == _stricmp("autoForceFullResSmoke", arg2)) {
                if(4 <= argC) {
                    bool bValue = 0 != atoi(args->ArgV(3));
                    bool bChanged = false;
                    for(auto it2=m_Streams.begin();it2!=m_Streams.end();it2++) {
                        bChanged = bChanged || it != it2 && it2->second.AutoForceFullResSmoke != bValue;
                        it2->second.AutoForceFullResSmoke = bValue;
                    }
                    if(bChanged) {
                        advancedfx::Warning("AFXWarning: Value is globally shared and has been changed on other streams.\n");
                    }
                    return;
                }

                advancedfx::Message(
                    "%s %s autoForceFullResSmoke 0|1\n"
                    "Current value: %i\n"
                    , arg0, arg1
                    , stream.AutoForceFullResSmoke ? 1 : 0
                );
                return;
            } else if(0 == _stricmp("beforeCommands", arg2)) {
                advancedfx::CSubCommandArgs subArgs(args, 3);
                g_AfxStreams.Console_Edit_RenderCommands(stream.BeforeCommands, &subArgs);
                return;
            } else if(0 == _stricmp("afterCommands", arg2)) {
                advancedfx::CSubCommandArgs subArgs(args, 3);
                g_AfxStreams.Console_Edit_RenderCommands(stream.AfterCommands, &subArgs);
                return;
            }
            else if(0 == _stricmp("viewModelAction", arg2)) {
                advancedfx::CSubCommandArgs subArgs(args, 3);
                StreamSettingsActionSubCommand(stream.ViewModelAction, &subArgs);
                return;
            }
            else if(0 == _stricmp("particlesAction", arg2)) {
                advancedfx::CSubCommandArgs subArgs(args, 3);
                StreamSettingsActionSubCommand(stream.ParticlesAction, &subArgs);
                return;
            }
            else if(0 == _stricmp("firstPersonLegsAction", arg2)) {
                advancedfx::CSubCommandArgs subArgs(args, 3);
                StreamSettingsActionSubCommand(stream.FirstPersonLegsAction, &subArgs);
                return;
            }
            else if(0 == _stricmp("shellsAction", arg2)) {
                advancedfx::CSubCommandArgs subArgs(args, 3);
                StreamSettingsActionSubCommand(stream.ShellsAction, &subArgs);
                return;
            }
            else if(0 == _stricmp("weaponsAction", arg2)) {
                advancedfx::CSubCommandArgs subArgs(args, 3);
                StreamSettingsActionSubCommand(stream.WeaponsAction, &subArgs);
                return;
            }
            else if(0 == _stricmp("playersAction", arg2)) {
                advancedfx::CSubCommandArgs subArgs(args, 3);
                StreamSettingsActionSubCommand(stream.PlayersAction, &subArgs);
                return;
            }
            else if(0 == _stricmp("worldAction", arg2)) {
                advancedfx::CSubCommandArgs subArgs(args, 3);
                StreamSettingsActionSubCommand(stream.WorldAction, &subArgs);
                return;
            }
            else if(0 == _stricmp("skyAction", arg2)) {
                advancedfx::CSubCommandArgs subArgs(args, 3);
                StreamSettingsActionSubCommand(stream.SkyAction, &subArgs);
                return;
            }
            else if(0 == _stricmp("smokeAction", arg2)) {
                advancedfx::CSubCommandArgs subArgs(args, 3);
                StreamSettingsActionSubCommand(stream.SmokeAction, &subArgs);
                return;
            }
            else if(0 == _stricmp("overlaysAction", arg2)) {
                advancedfx::CSubCommandArgs subArgs(args, 3);
                StreamSettingsActionSubCommand(stream.OverlaysAction, &subArgs);
                return;
            }
        }

        advancedfx::Message(
            "%s %s record [...] - Whether to record.\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s capture [...] - When to capture.\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s settings [...] - Output settings to use.\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s captureType  [...] - The type of capture.\n"
            , arg0, arg1
        );        
        advancedfx::Message(
            "%s %s depthCompositeSmoke [...] - If depth capture wheter or not to composite smoke.\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s depthVal [...] - Minimum depth value.\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s depthValMax [...] - Maximum depth value.\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s depthChannels [...] - How to transform depth into color channels.\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s depthMode [...] - How transform the depth view.\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s clear  [...] - If and with what color to override the main render target clear (stream background).\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s clearBeforeUI  [...] - If and with what color to clear before Panorama UI.\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s autoForceFullResSmoke [...] - When capturing smoke depth: If to force the engine into full resolution smoke passes (recommended). (Globally shared!)\n"
            , arg0, arg1
        );
                                                advancedfx::Message(
            "%s %s beforeCommands [...] - Commands to execute before the stream is rendered.\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s afterCommands [...] - Commands to execute before the stream is rendered.\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s viewModelAction [...]\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s particlesAction [...]\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s firstPersonLegsAction [...]\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s shellsAction [...]\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s weaponsAction [...]\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s playersAction [...]\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s worldAction [...]\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s skyAction [...]\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s smokeAction [...]\n"
            , arg0, arg1
        );
        advancedfx::Message(
            "%s %s overlaysAction [...]\n"
            , arg0, arg1
        );
		return;
    }

	advancedfx::Message(
		"%s <sUniqueStreamName> [...] - Edit stream with given name.\n"
		, arg0
	);
}


void CAfxStreams::Console_Print() {
	advancedfx::Message(
		"============================================================\n"
		"name (recording preset)\n"
	);
	std::list<std::map<std::string,CStreamSettings>::iterator> streams[3];
	int index = 0;
	for (auto it = m_Streams.begin(); it != m_Streams.end(); it++)
	{
		if(it->second.Record)
			streams[1].emplace_back(it);
		else
			streams[2].emplace_back(it);
		++index;
	}

	for(int i=0;i<3;i++) {
		if(0 == streams[i].size()) continue;
		advancedfx::Message("\n");
		switch(i) {
		case 0:
            advancedfx::Message("[*] PREVIEWING\n");
			break;
		case 1:
            advancedfx::Message("[R] RECORD ON\n");
			break;
		case 2:
            advancedfx::Message("[-] RECORD OFF\n");
			break;
		}
		for(auto it = streams[i].begin(); it != streams[i].end(); it++) {
			const char * streamName = (*it)->first.c_str();
			const char * settingName = "";
			if(advancedfx::CRecordingSettings * setting =  (*it)->second.Settings) {
				settingName = setting->GetName();
			}
			/*if(i == 0 && streams[i].size() > 1 || it->PreviewSlot > 0) {
				Tier0_Msg("%i: %s (%s) @%i\n", it->Index, streamName, settingName, it->PreviewSlot);
			} else*/ {
				advancedfx::Message("%s (%s)\n", streamName, settingName);
			}
		}
	}

	advancedfx::Message(
		"\n"
		"==== Total streams: %i ====\n",
		index
	);
}

void CAfxStreams::Console_Remove(advancedfx::ICommandArgs* args) {
	int argC = args->ArgC();
	char const* arg0 = args->ArgV(0);

    if(2 <= argC) {
        char const* arg1 = args->ArgV(1);

        auto it = m_Streams.find(arg1);

        if(it == m_Streams.end()) {
            advancedfx::Warning("AFXERROR: No stream named \"%s\" exists.\n", arg1);
            return;            
        }

        m_Streams.erase(it);
        return;
    }

	advancedfx::Message(
		"%s <sUniqueStreamName> [...] - Remove stream with given name.\n"
		, arg0
	);
}

void AfxHookSourceRs_Engine_OnRecordStart(const char * take_folder_path);

extern CamPath g_CamPath;

void CAfxStreams::RecordStart()
{
	RecordEnd();
	m_RecordedSourceFrameCount.store(0, std::memory_order_release);
	g_AfxCaptureWriterFailureCount.store(0, std::memory_order_release);

	advancedfx::Message("Starting recording ... ");
	
	if(UTF8StringToWideString(m_RecordName.c_str(), m_TakeDir)
		&& (!m_RecordTakeSubfolder
			|| (m_TakeDir.append(L"\\take"), SuggestTakePath(m_TakeDir.c_str(), 4, m_TakeDir)))
		// Without a take subfolder the caller owns the folder (the render driver creates it first).
		&& CreatePath(m_TakeDir.c_str(), m_TakeDir, !m_RecordTakeSubfolder)
	)
	{
		m_Recording = true;
		m_StartMovieWavUsed = false;

		std::string utf8TakeDir;
		bool utf8TakeDirOk = WideStringToUTF8String(m_TakeDir.c_str(), utf8TakeDir);
        SOURCESDK::CS2::Cvar_s * handle_host_framerate = SOURCESDK::CS2::g_pCVar->GetCvar(SOURCESDK::CS2::g_pCVar->FindConVar("host_framerate", false).Get());
        SOURCESDK::CS2::Cvar_s * handle_engine_no_focus_sleep = SOURCESDK::CS2::g_pCVar->GetCvar(SOURCESDK::CS2::g_pCVar->FindConVar("engine_no_focus_sleep", false).Get());
        SOURCESDK::CS2::Cvar_s * handle_r_always_render_all_windows = SOURCESDK::CS2::g_pCVar->GetCvar(SOURCESDK::CS2::g_pCVar->FindConVar("r_always_render_all_windows", false).Get());
        SOURCESDK::CS2::Cvar_s * handle_r_wait_on_present = SOURCESDK::CS2::g_pCVar->GetCvar(SOURCESDK::CS2::g_pCVar->FindConVar("r_wait_on_present", false).Get());
        
        m_UsedHostFramerRateValue = GetOverrideFps();

        if(m_UsedHostFramerRateValue && handle_host_framerate) {
            m_OldValue_host_framerate = handle_host_framerate->m_Value.m_flValue;
            handle_host_framerate->m_Value.m_flValue = GetOverrideFpsValue();
        }

        if(handle_engine_no_focus_sleep) {
            m_OldValue_engine_no_focus_sleep = handle_engine_no_focus_sleep->m_Value.m_i32Value;
            handle_engine_no_focus_sleep->m_Value.m_i32Value = 0;
        }

        if(handle_r_always_render_all_windows) {
            m_OldValue_r_always_render_all_windows = handle_r_always_render_all_windows->m_Value.m_bValue;
            handle_r_always_render_all_windows->m_Value.m_bValue = true;
        }

        if(handle_r_wait_on_present) {
            m_OldValue_r_wait_on_present = handle_r_wait_on_present->m_Value.m_bValue;
            // The capture maps each frame's staging copy one Present later, and that Map blocks
            // until the copy is done, so the recorder does not need the engine to wait for the
            // GPU every frame. Waiting serialises CPU and GPU work: 2026-10-18, de_ancient at
            // 2560x1351, 300 fps renders with the custom lighting off took 10.4 ms per output frame
            // waiting and 8.2 ms without (A/B/B/A, 900 frames each); with the lighting on, 60 fps
            // renders went from 36.6 to 33.3 ms. Every take wrote its full frame count.
            if (g_RecordWaitOnPresent.load(std::memory_order_relaxed))
                handle_r_wait_on_present->m_Value.m_bValue = true;
        }

		float host_framerate = m_OverrideFps ? m_OverrideFpsValue : (handle_host_framerate != nullptr ? handle_host_framerate->m_Value.m_flValue : 0);
		double frameTime;
		if (1.0 <= host_framerate) {
			m_StartHostFrameRateValue = host_framerate;
			frameTime = 1.0 / host_framerate;
		}
		else {
			m_StartHostFrameRateValue = host_framerate ? 1.0f / host_framerate : 0.0f;
			frameTime = host_framerate;
		}

		if (0 == frameTime) {
			advancedfx::Warning("You probably forgot to set host_framerate to the FPS you want to record.\n");
			if (nullptr == handle_host_framerate) {
				advancedfx::Warning("You probably forgot to set mirv_streams record fps to the FPS you want to record.\n");
			}
		}

		if(m_CampathAutoSave && 0 < g_CamPath.GetSize())
		{
			std::wstring campathFileName(m_TakeDir);
			campathFileName.append(L"\\campath.xml");
			if(!g_CamPath.Save(campathFileName.c_str()))
				advancedfx::Warning("Error: Failed saving campath.xml to take folder.\n");
		}        

		if (m_CamExport)
		{
			std::wstring camFileName(m_TakeDir);
			camFileName.append(L"\\cam_main.cam");

			m_CamExportSet = true;
			g_S2CamIO.SetCamExport(new CamExport(camFileName.c_str()));
		}

		if(m_RecordScreen->Enabled) {
            auto videoStreamCreator = m_RecordScreen->Settings->CreateOutVideoStreamCreator(
                *this,
                *this,
                m_StartHostFrameRateValue,
                ""
            );
			CreateCapture(videoStreamCreator);
            videoStreamCreator->Release();
		}

        m_AutoForceFullReSmoke = false;
        m_CompositeSmoke = false;
        m_PassNeedsMainReference = false;
        // Screen recording captures at BeforePresent, so it always counts as after-UI.
        m_RecordingCapturesAfterUi = m_RecordScreen && m_RecordScreen->Enabled;

        for(auto it = m_Streams.begin(); it != m_Streams.end(); it++) {
            if(!it->second.Record) continue;
            m_CompositeSmoke = m_CompositeSmoke || it->second.WantsSmokeComposite();
            if(it->second.Capture == CStreamSettings::Capture_e::BeforePresent)
                m_RecordingCapturesAfterUi = true;
            m_AutoForceFullReSmoke = m_AutoForceFullReSmoke || it->second.WantsFullResSmoke();

            if(it->second.PassElements == (int)Filmmaker::VisibleElements::OnlyWeapon)
                m_PassNeedsMainReference = true;
            if(it->second.CanCaptureInMainPass())
                m_RecordingMainPass.emplace_back(this, it->second);
            else
                m_RecordingExtraPasses.emplace(this, it->second);
        }
        // Players Only is the NoGun render masked to what is closer than the World Only render of
        // the same frame (render order Main, WorldOnly, NoGun; RenderPassPlan.h says why it is not
        // a chroma repaint). One output-less World Only render supplies that depth when no World
        // Only pass is recorded; with one, the two share the render.
        for(auto it = m_Streams.begin(); it != m_Streams.end(); it++) {
            if(!it->second.Record || it->second.PassElements != (int)Filmmaker::VisibleElements::OnlyPlayers) continue;
            CStreamSettings ref(it->second);
            ref.Name = L"_worldref";
            ref.PassType = (int)Filmmaker::PassType::Depth;
            ref.PassElements = (int)Filmmaker::VisibleElements::OnlyWorld;
            ref.PassReferenceOnly = true;
            m_RecordingExtraPasses.emplace(this, ref);
            break;
        }


        if (m_CompositeSmoke) {
            auto& pRenderPassCommands = g_RenderCommands.EngineThread_GetCommands();
            {
                auto& queue = pRenderPassCommands.BeginReliable;
                queue.Push([]() {
                    g_bCompositeSmoke = true;
                });
            }
        }

		advancedfx::Message("done.\n");

		advancedfx::Message("Recording to \"%s\".\n", utf8TakeDirOk ? utf8TakeDir.c_str() : "?");

		m_StartMovieWavUsed = m_StartMovieWav;

		if (m_StartMovieWavUsed)
		{
            SOURCESDK::CS2::ConCommandHandle handle_startmovie = SOURCESDK::CS2::g_pCVar->FindCommand( "startmovie", false );
            if(handle_startmovie.IsValid()) {
                const char * pszArgs[3] = {"startmovie",ADVANCEDFX_STARTMOVIE_WAV_KEY,"wav"};
                SOURCESDK::CS2::g_pCVar->DispatchConCommand(handle_startmovie, SOURCESDK::CS2::CCommandContext(SOURCESDK::CS2::CT_FIRST_SPLITSCREEN_CLIENT,0), SOURCESDK::CS2::CCommand(3,pszArgs));
            } else advancedfx::Warning("AFXERROR: startmovie command not found, wav recording not possible.");
		}

        AfxHookSourceRs_Engine_OnRecordStart(utf8TakeDirOk ? utf8TakeDir.c_str() : nullptr);
	}
	else
	{
		advancedfx::Message("FAILED");
		advancedfx::Warning("Error: Failed to create directories for \"%s\".\n", m_RecordName.c_str());
	}

}


void AfxHookSourceRs_Engine_OnRecordEnd();

void CAfxStreams::RecordEnd()
{
	if(m_Recording)
	{
        g_CurrentPassRenderKey.store(-1, std::memory_order_release);
        AfxHookSourceRs_Engine_OnRecordEnd();

		advancedfx::Message("Finishing recording ... ");
		if (m_StartMovieWavUsed)
		{
            SOURCESDK::CS2::ConCommandHandle handle_endmovie = SOURCESDK::CS2::g_pCVar->FindCommand( "endmovie", false );
            if(handle_endmovie.IsValid()) {
                const char * pszArgs[1] = {"endmovie"};
                SOURCESDK::CS2::g_pCVar->DispatchConCommand(handle_endmovie, SOURCESDK::CS2::CCommandContext(SOURCESDK::CS2::CT_FIRST_SPLITSCREEN_CLIENT,0), SOURCESDK::CS2::CCommand(1,pszArgs));
            } else advancedfx::Warning("AFXERROR: endmovie command not found, stopping the wav recording not possible.");

		}

		if(m_CamExportSet) {
			m_CamExportSet = false;
			g_S2CamIO.SetCamExport(nullptr);
		}

        m_RecordingExtraPasses.clear();
        m_RecordingMainPass.clear();
        m_RecordingCapturesAfterUi = false;

        if(m_RecordScreen->Enabled) {
            EndCapture();
        }

        if(m_CompositeSmoke) {
            auto & pRenderPassCommands = g_RenderCommands.EngineThread_GetCommands();
            {
                auto & queue = pRenderPassCommands.FinalizeReliable;
                queue.Push([](){
                    g_bCompositeSmoke = false;
                }); 
            }
            m_CompositeSmoke = false;
        }

        SOURCESDK::CS2::Cvar_s * handle_host_framerate = SOURCESDK::CS2::g_pCVar->GetCvar(SOURCESDK::CS2::g_pCVar->FindConVar("host_framerate", false).Get());
        SOURCESDK::CS2::Cvar_s * handle_engine_no_focus_sleep = SOURCESDK::CS2::g_pCVar->GetCvar(SOURCESDK::CS2::g_pCVar->FindConVar("engine_no_focus_sleep", false).Get());
        SOURCESDK::CS2::Cvar_s * handle_r_always_render_all_windows = SOURCESDK::CS2::g_pCVar->GetCvar(SOURCESDK::CS2::g_pCVar->FindConVar("r_always_render_all_windows", false).Get());
        SOURCESDK::CS2::Cvar_s * handle_r_wait_on_present = SOURCESDK::CS2::g_pCVar->GetCvar(SOURCESDK::CS2::g_pCVar->FindConVar("r_wait_on_present", false).Get());

        if(m_UsedHostFramerRateValue && handle_host_framerate) {
            handle_host_framerate->m_Value.m_flValue = m_OldValue_host_framerate;
        }

        if(handle_r_wait_on_present) {
            handle_r_wait_on_present->m_Value.m_bValue = m_OldValue_r_wait_on_present;
        }

        if(handle_engine_no_focus_sleep) {
            handle_engine_no_focus_sleep->m_Value.m_i32Value = m_OldValue_engine_no_focus_sleep;
        }

        if(handle_r_always_render_all_windows) {
            handle_r_always_render_all_windows->m_Value.m_bValue = m_OldValue_r_always_render_all_windows;
        }

    	advancedfx::Message("done.\n");
	}

	m_Recording = false;
}

